#!/usr/bin/env python3
"""Builds src/program_icons.zig from the icons in data/program-icons: one SVG each, with a
single path on a 24 by 24 grid, and its tile color in colors.txt. See the README there for
where the icons come from. Run from anywhere: python3 scripts/gen-program-icons.py
"""
import pathlib
import re

root = pathlib.Path(__file__).resolve().parents[1]
icons = root / "data/program-icons"

lines = [
    "//! Generated by scripts/gen-program-icons.py from data/program-icons.",
    "//! Don't edit by hand.",
    "",
    "pub const Icon = struct { slug: []const u8, color: u32, path: []const u8 };",
    "",
    "pub const icons = [_]Icon{",
]
entries = {}
for line in (icons / "colors.txt").read_text().splitlines():
    if not line.strip() or line.startswith("#"):
        continue
    slug, color = line.split()
    svg = (icons / f"{slug}.svg").read_text()
    entries[slug] = (color.upper(), " ".join(re.findall(r'<path[^>]*\bd="([^"]+)"', svg)))

for slug, (color, path) in sorted(entries.items()):
    data = path.replace("\\", "\\\\").replace('"', '\\"')
    lines.append(f'    .{{ .slug = "{slug}", .color = 0xFF{color}, .path = "{data}" }},')
lines += ["};", ""]
(root / "src/program_icons.zig").write_text("\n".join(lines))
print(f"{len(entries)} icons")
